//! Markdown report emitter (the default `report.md` output).

use std::fmt::Write as _;

use super::{Issue, RenderOptions, Report};

pub fn render(report: &Report, opts: RenderOptions) -> String {
    let mut out = String::new();
    let _ = writeln!(out, "# Aderyn Analysis Report\n");
    let _ = writeln!(
        out,
        "This report was generated by lancer-aderyn v{}\n",
        report.tool_version
    );

    // ---- Summary ----------------------------------------------------------
    let _ = writeln!(out, "## Summary\n");
    let _ = writeln!(out, "- Total Source Units: {}", report.files_summary.len());
    let _ = writeln!(out, "- Total nSLOC: {}", report.total_sloc);
    let _ = writeln!(out, "- High Issues: {}", report.high_issue_count());
    if !opts.highs_only {
        let _ = writeln!(out, "- Low Issues: {}", report.low_issue_count());
    }
    let _ = writeln!(out);

    // ---- Files summary ----------------------------------------------------
    let _ = writeln!(out, "## Files Summary\n");
    let _ = writeln!(out, "| File | nSLOC |");
    let _ = writeln!(out, "|------|-------|");
    for f in &report.files_summary {
        let _ = writeln!(out, "| {} | {} |", f.file_path, f.n_sloc);
    }
    let _ = writeln!(out, "| **Total** | **{}** |\n", report.total_sloc);

    // ---- Issue table of contents -----------------------------------------
    let _ = writeln!(out, "## Issues\n");
    if !report.highs.is_empty() {
        let _ = writeln!(out, "### High Issues\n");
        for (i, issue) in report.highs.iter().enumerate() {
            render_issue(&mut out, "H", i + 1, issue, opts);
        }
    }
    if !opts.highs_only && !report.lows.is_empty() {
        let _ = writeln!(out, "### Low Issues\n");
        for (i, issue) in report.lows.iter().enumerate() {
            render_issue(&mut out, "L", i + 1, issue, opts);
        }
    }

    if report.highs.is_empty() && (opts.highs_only || report.lows.is_empty()) {
        let _ = writeln!(out, "No issues found. 🎉\n");
    }

    out
}

fn render_issue(out: &mut String, prefix: &str, n: usize, issue: &Issue, opts: RenderOptions) {
    let _ = writeln!(out, "#### [{prefix}-{n}] {}\n", issue.title);
    let _ = writeln!(out, "{}\n", issue.description);
    let _ = writeln!(out, "*Detector: `{}`*\n", issue.detector_name);
    let _ = writeln!(out, "<details><summary>{} Found Instances</summary>\n", issue.instances.len());
    for inst in &issue.instances {
        let _ = writeln!(out, "- Found in `{}` Line: {}", inst.contract_path, inst.line_no);
        if !opts.no_snippets && !inst.snippet.is_empty() {
            let _ = writeln!(out, "\n  ```solidity\n  {}\n  ```", inst.snippet);
        }
        if let Some(hint) = &inst.hint {
            let _ = writeln!(out, "  > {hint}");
        }
    }
    let _ = writeln!(out, "\n</details>\n");
}
